		$(&#39;.CSU4&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Guide to Korvosa/Guide de Korvosa)&quot;);
		$(&#39;.CSU5&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (The Worldwound/Guide de la Plaie du monde)&quot;);
		$(&#39;.CSU6&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Isles of the Shackles/Guide des Cha&#238;nes)&quot;);
